// Init Run State
// Reads the form, sets up configuration and the loop's state object.
// Edit CONFIG below to tune the workflow without touching other nodes.

const CONFIG = {
  aiModel: 'gemini-3.7-flash',      // any Gemini model that supports generateContent
  aiMinIntervalMs: 4500,            // minimum gap between Gemini calls (free-tier friendly)
  firecrawlDelayMs: 700,            // pause between Firecrawl searches
  maxConsecutiveApiErrors: 3,       // stop the run if Firecrawl keeps failing
  contactRoles: [
    'CTO', '"Head of Engineering"', '"Engineering Manager"', 'Founder', 'CEO',
    '"Talent Acquisition"', '"HR Manager"',
  ],
  // Job boards: site filter for the query + regex a single posting URL must match.
  boards: {
    'LinkedIn Jobs': { site: 'linkedin.com/jobs/view', match: 'linkedin\\.com\\/jobs\\/view\\/' },
    'Rozee.pk':      { site: 'rozee.pk', match: 'rozee\\.pk\\/' },
    'Indeed':        { site: 'indeed.com', match: 'indeed\\.com\\/' },
    'Bayt':          { site: 'bayt.com', match: 'bayt\\.com\\/[a-z]{2}\\/.*job' },
    'Greenhouse':    { site: 'greenhouse.io', match: 'greenhouse\\.io\\/[^/]+\\/jobs\\/\\d+' },
    'Lever':         { site: 'jobs.lever.co', match: 'jobs\\.lever\\.co\\/[^/]+\\/[0-9a-f-]{8,}' },
    'Any website':   { site: '', match: '^https?:\\/\\/' },
  },
};

const form = $('Lead Intake Form').first().json;

function asList(value) {
  if (Array.isArray(value)) return value.map(String);
  const s = String(value ?? '').trim();
  if (!s) return [];
  try {
    const parsed = JSON.parse(s);
    if (Array.isArray(parsed)) return parsed.map(String);
  } catch (e) {}
  return s.split(',').map((x) => x.trim()).filter(Boolean);
}

const targetLeads = Number(form['Maximum leads']);
if (![10, 25, 50].includes(targetLeads)) {
  throw new Error(`Invalid Maximum leads value: ${form['Maximum leads']}`);
}

const mode = String(form.Mode || '').toLowerCase().includes('job') ? 'jobs' : 'clients';
const modeLabel = mode === 'jobs' ? 'Jobs' : 'Clients';

let boardNames = asList(form['Job boards']).filter((b) => CONFIG.boards[b]);
if (!boardNames.length) boardNames = ['LinkedIn Jobs', 'Rozee.pk', 'Indeed'];
const boards = boardNames.map((name) => ({ name, ...CONFIG.boards[name] }));

const tbsMap = {
  'Past 24 hours': 'qdr:d',
  'Past week': 'qdr:w',
  'Past month': 'qdr:m',
  'Any time': '',
};
const tbs = tbsMap[form['Posted within']] ?? 'qdr:w';

const minScore = Math.min(5, Math.max(1, Number(form['Minimum fit score (1-5)'] || 3)));
const rankingField = String(form['Ranking method'] || '').toLowerCase();
const rankingMode = rankingField.includes('no ranking') ? 'none'
  : rankingField.includes('keyword') ? 'keyword' : 'ai';
const rankingLabel = { ai: 'AI (Gemini)', keyword: 'Keyword', none: 'None' }[rankingMode];

const findContacts = mode === 'clients'
  && String(form['Find a decision-maker? (clients mode)'] || 'Yes').toLowerCase().startsWith('y');

const existingRows = $('Load Existing Leads').all()
  .filter((i) => i.json && String(i.json['Job URL'] || '').trim());

return [{
  json: {
    form,
    mode,
    modeLabel,
    config: {
      aiModel: CONFIG.aiModel,
      aiMinIntervalMs: CONFIG.aiMinIntervalMs,
      firecrawlDelayMs: CONFIG.firecrawlDelayMs,
      maxConsecutiveApiErrors: CONFIG.maxConsecutiveApiErrors,
      contactRoles: CONFIG.contactRoles,
      boards,
      tbs,
      minScore: rankingMode === 'none' ? 1 : minScore,
      findContacts,
      rankingMode,
      rankingLabel,
      useAi: rankingMode === 'ai',
    },
    targetLeads,
    newLeadsSaved: 0,
    lowFitCount: 0,
    duplicateCount: 0,
    notJobCount: 0,
    aiErrorCount: 0,
    consecutiveUnsuccessfulAttempts: 0,
    consecutiveApiErrors: 0,
    lastApiError: '',
    lastAiCallAt: 0,
    maxRetries: Math.max(40, targetLeads * 3),
    maxAttempts: targetLeads * 25,
    attemptIndex: 0,
    seenUrls: [],
    seenKeys: [],
    candidateQueue: [],
    existingLeadCount: existingRows.length,
    searchRunId: String($execution.id),
    startedAt: $now.toISO(),
    shouldContinue: true,
    lastOutcome: null,
    status: 'running',
    useQueue: false,
  },
}];

// Build Search Query
// Uses queued results first; otherwise builds the next job-board query.
// Rotates boards and query patterns, then broadens when results dry up.

const state = $input.first().json;
const cfg = state.config;
const form = state.form;
const attempt = Number(state.attemptIndex || 0);
const consec = Number(state.consecutiveUnsuccessfulAttempts || 0);
const candidateQueue = Array.isArray(state.candidateQueue) ? state.candidateQueue : [];

// 1) Drain queued results before paying for another search
if (candidateQueue.length > 0) {
  return [{
    json: { ...state, useQueue: true, searchQuery: '[queue]', firecrawlBody: {}, candidateQueue },
  }];
}

// 2) Polite pacing (longer after an API error)
if (attempt > 0) {
  const base = Number(cfg.firecrawlDelayMs || 700);
  const delay = state.lastOutcome === 'api_error' ? 5000
    : consec >= 20 ? base * 2 : consec >= 10 ? base * 1.4 : base;
  await new Promise((resolve) => setTimeout(resolve, delay));
}

const role = String(form['Role or skill keywords'] || '').replace(/\s+/g, ' ').trim();
const location = String(form.Location || '').trim();

const roleParts = role.split(/\s*,\s*|\s+OR\s+/i).map((s) => s.trim()).filter(Boolean);
const locParts = location.split(/[\/,|]/).map((s) => s.trim()).filter(Boolean);
const isRemote = (s) => /remote|anywhere|worldwide/i.test(s);

function pick(arr, i) { return arr.length ? arr[i % arr.length] : ''; }
function quote(s) { return s ? `"${s}"` : ''; }

const boards = cfg.boards;
const board = boards[attempt % boards.length];
const round = Math.floor(attempt / boards.length);

const roleTerm = pick(roleParts, round) || role;
const roleOr = roleParts.length > 1 ? `(${roleParts.map(quote).join(' OR ')})` : quote(roleTerm);
const locTerm = pick(locParts, Math.floor(round / 2)) || location;
const locQ = isRemote(locTerm) ? 'remote' : quote(locTerm);
const locPlain = isRemote(locTerm) ? 'remote' : locTerm;

const sitePart = board.site ? `site:${board.site}` : '(hiring OR careers OR "job opening")';

const patterns = [
  () => `${sitePart} ${quote(roleTerm)} ${locQ}`,
  () => `${sitePart} ${roleOr} ${locQ}`,
  () => `${sitePart} intitle:${quote(roleTerm)} ${locPlain}`,
  () => `${sitePart} ${quote(roleTerm)} ${locPlain} hiring`,
  () => `${sitePart} ${roleOr} ${locPlain}`,
];

const clean = (q) => q.replace(/""/g, '').replace(/\s+/g, ' ').trim();
let query = clean(patterns[round % patterns.length]());

// Progressive broadening when stuck
if (consec >= 12) query = clean(`${sitePart} ${roleOr} ${locPlain}`);
if (consec >= 24) query = clean(`${sitePart} ${roleTerm} ${locParts[0] || ''}`);

let tbs = cfg.tbs;
if (consec >= 25 && tbs === 'qdr:d') tbs = 'qdr:w';
if (consec >= 35 && tbs === 'qdr:w') tbs = 'qdr:m';

const firecrawlBody = { query, limit: consec >= 15 ? 15 : 10 };
if (tbs) firecrawlBody.tbs = tbs;
if (locTerm && !isRemote(locTerm) && consec < 12 && attempt % 2 === 0) {
  firecrawlBody.location = locTerm;
}

return [{
  json: {
    ...state,
    useQueue: false,
    searchQuery: query,
    currentBoard: board.name,
    firecrawlBody,
    candidateQueue: [],
  },
}];

// Extract Job Candidate
// Turns Firecrawl search results into one job candidate (and queues the rest).
// Skips listing/search pages, non-posting URLs and anything already seen.

const state = $('Build Search Query').item.json;
const cfg = state.config;
const form = state.form;

const boards = cfg.boards.map((b) => ({ ...b, re: new RegExp(b.match, 'i') }));
const excludedDomains = ['youtube.com', 'wikipedia.org', 'facebook.com', 'instagram.com', 'reddit.com'];
const listingTitle = [
  /\b\d[\d,]*\+?\s+.*\bjobs?\b/i,              // "120 Flutter Developer jobs in Lahore"
  /\bjobs?\s*(in|near)\b.*\(with salaries\)/i,
  /\b(vacancies|job openings|jobs and careers)\b/i,
  /^jobs?\s+(in|for)\b/i,
];

function normalizeJobUrl(raw) {
  const s = String(raw || '').trim();
  if (!s) return '';
  let u;
  try { u = new URL(s); } catch (e) { return s.toLowerCase().replace(/[?#].*$/, '').replace(/\/+$/, ''); }
  const host = u.hostname.toLowerCase().replace(/^www\./, '');
  if (/(^|\.)linkedin\.com$/.test(host)) {
    const m = u.pathname.match(/\/jobs\/view\/(?:[^/]*?-)?(\d{6,})/);
    if (m) return `https://www.linkedin.com/jobs/view/${m[1]}`;
  }
  if (/(^|\.)indeed\.com$/.test(host)) {
    const jk = u.searchParams.get('jk') || u.searchParams.get('vjk');
    if (jk) return `https://www.indeed.com/viewjob?jk=${jk}`;
  }
  const path = u.pathname.replace(/\/+$/, '');
  return `https://${host}${path}`.toLowerCase();
}

function dedupeSlug(s) {
  return String(s || '').toLowerCase()
    .replace(/\b(pvt|private|ltd|limited|inc|llc|co|company|corp)\b\.?/g, '')
    .replace(/[^a-z0-9]+/g, '');
}

// Seen = URLs handled this run + URLs already in the sheet for this mode
const seen = new Set(state.seenUrls || []);
for (const row of $('Load Existing Leads').all()) {
  const j = row.json || {};
  if (String(j.Mode || '') !== state.modeLabel) continue;
  const u = normalizeJobUrl(j['Job URL']);
  if (u) seen.add(u);
}

function boardFor(url) {
  // Most specific board first; "Any website" last
  const specific = boards.filter((b) => b.site);
  for (const b of specific) if (b.re.test(url)) return b.name;
  const any = boards.find((b) => !b.site);
  return any && any.re.test(url) ? any.name : '';
}

// Heuristic title parse; Gemini refines these later
function parseTitle(title, url) {
  let t = String(title || '').replace(/\s+/g, ' ').trim()
    .replace(/\s*[|\-–—]\s*(LinkedIn|Indeed(\.com)?|Rozee\.pk|Bayt\.com|Greenhouse|Lever)\s*$/i, '')
    .replace(/\s*(\.\.\.|…)\s*$/, '');
  let company = '';
  let role = '';
  let loc = '';
  let m;
  if ((m = t.match(/^(.+?) hiring (.+?) in (.+)$/i))) { [, company, role, loc] = m; }
  else if ((m = t.match(/^Job Application for (.+?) at (.+)$/i))) { [, role, company] = m; }
  else if ((m = t.match(/^(.+?) jobs? in (.+?) at (.+)$/i))) { [, role, loc, company] = m; }
  else {
    const parts = t.split(/\s+[|\-–—]\s+/).map((s) => s.trim()).filter(Boolean);
    if (/jobs\.lever\.co/i.test(url)) { [company = '', role = ''] = parts; }
    else { [role = '', company = '', loc = ''] = parts; }
  }
  if (!company) {
    const gh = url.match(/greenhouse\.io\/([^/]+)\/jobs/i) || url.match(/jobs\.lever\.co\/([^/]+)/i);
    if (gh) company = gh[1].replace(/[-_]+/g, ' ');
  }
  return { company: company.trim(), role: role.trim(), loc: loc.trim() };
}

function basePayload(extra = {}) {
  return {
    ...state,
    hasCandidate: false,
    outcome: 'empty',
    normalizedUrl: '',
    apiError: '',
    'Date Added': $now.toISODate(),
    'Time Added': $now.toFormat('HH:mm:ss'),
    'Mode': state.modeLabel,
    'Company': '',
    'Job Title': '',
    'Location': '',
    'Job Board': '',
    'Job URL': '',
    'Snippet': '',
    'Fit Score': '',
    'Fit Reason': '',
    'Angle / Tip': '',
    'Contact Name': '',
    'Contact Title': '',
    'Contact LinkedIn': '',
    'Search Keywords': form['Role or skill keywords'] ?? '',
    'Run By': form['Your name'] ?? '',
    'Search Run ID': state.searchRunId,
    'Status': state.mode === 'jobs' ? 'To apply' : 'New',
    'Dedupe Key': '',
    candidateQueue: Array.isArray(state.candidateQueue) ? state.candidateQueue : [],
    ...extra,
  };
}

function toCandidate(r, queue) {
  const p = parseTitle(r.title, r.url);
  const key = p.company && p.role
    ? `${state.mode}|${dedupeSlug(p.company)}|${dedupeSlug(p.role)}` : '';
  return basePayload({
    hasCandidate: true,
    outcome: 'candidate',
    normalizedUrl: r.normalizedUrl,
    'Company': p.company,
    'Job Title': p.role,
    'Location': p.loc,
    'Job Board': r.board,
    'Job URL': r.normalizedUrl,
    'Snippet': String(r.description || '').slice(0, 500),
    'Dedupe Key': key,
    rawTitle: r.title,
    candidateQueue: queue,
  });
}

// A) Use a queued result
if (state.useQueue && state.candidateQueue && state.candidateQueue.length) {
  const [next, ...rest] = state.candidateQueue;
  if (next.normalizedUrl && !seen.has(next.normalizedUrl)) {
    return [{ json: toCandidate(next, rest) }];
  }
  return [{ json: basePayload({ outcome: 'seen', candidateQueue: rest }) }];
}

// B) Parse the Firecrawl response
let response = {};
try { response = $('Firecrawl Search').item.json; } catch (e) { response = $input.first().json; }

if (!response || response.success === false || (response.error && !response.data)) {
  const msg = response && (response.error?.message || response.error || response.message);
  return [{ json: basePayload({ outcome: 'api_error', apiError: String(msg || 'Firecrawl request failed') }) }];
}

let results = [];
if (Array.isArray(response?.data?.web)) results = response.data.web;
else if (Array.isArray(response?.data)) results = response.data;
else if (Array.isArray(response?.web)) results = response.web;

if (!results.length) return [{ json: basePayload({ outcome: 'empty' }) }];

const usable = [];
const batch = new Set();
let sawSeen = false;
for (const r of results) {
  const url = String(r.url ?? r.link ?? '').trim();
  const title = String(r.title ?? '').trim();
  const description = String(r.description ?? r.snippet ?? '').trim();
  if (!url || !title) continue;
  if (excludedDomains.some((d) => url.toLowerCase().includes(d))) continue;
  if (listingTitle.some((re) => re.test(title))) continue;
  const board = boardFor(url);
  if (!board) continue;
  const normalizedUrl = normalizeJobUrl(url);
  if (!normalizedUrl) continue;
  if (seen.has(normalizedUrl)) { sawSeen = true; continue; }
  if (batch.has(normalizedUrl)) continue;
  batch.add(normalizedUrl);
  usable.push({ url, title, description, normalizedUrl, board });
}

if (!usable.length) {
  return [{ json: basePayload({ outcome: sawSeen ? 'seen' : 'invalid' }) }];
}

return [{ json: toCandidate(usable[0], usable.slice(1)) }];

// Rule-Based Score
// Used when Ranking method is "Keyword ranking (no AI)" or "No ranking (save all)".
// No API calls. Produces the same fields as Parse AI Result so the rest of the flow is unchanged.

const lead = $input.first().json;
const cfg = lead.config;
const form = lead.form;
const out = { ...lead, aiError: '' };

const STOP = new Set(('and the for with from that this are you your our will have has who into able ' +
  'years year experience work working team teams strong good great skills skill job role looking ' +
  'want based plus etc also using use well can all any new more other per about over' +
  ' developer engineer senior junior lead').split(/\s+/));

const words = (s) => String(s || '').toLowerCase().split(/[^a-z0-9+#.]+/)
  .map((w) => w.replace(/\.+$/, '')).filter((w) => w.length >= 3 && !STOP.has(w));

// Known-keys duplicate check (same rule as the AI path)
const knownKeys = new Set(lead.seenKeys || []);
for (const row of $('Load Existing Leads').all()) {
  const k = row.json && row.json['Dedupe Key'];
  if (k) knownKeys.add(String(k));
}
const isDuplicate = Boolean(out['Dedupe Key']) && knownKeys.has(out['Dedupe Key']);

if (cfg.rankingMode === 'none') {
  out['Fit Score'] = '';
  out['Fit Reason'] = 'Not ranked';
  out.outcome = isDuplicate ? 'duplicate' : 'qualified';
} else {
  const title = String(lead.rawTitle || lead['Job Title'] || '').toLowerCase();
  const text = `${title} ${String(lead.Snippet || '').toLowerCase()}`;

  // 1) Role match: full phrase in title = 2, some role words in title = 1
  const rolePhrases = String(form['Role or skill keywords'] || '').toLowerCase()
    .split(/\s*,\s*|\s+or\s+/).map((s) => s.trim()).filter(Boolean);
  let rolePts = 0;
  let roleNote = 'no role match';
  if (rolePhrases.some((p) => title.includes(p))) { rolePts = 2; roleNote = 'role matches title'; }
  else if (rolePhrases.some((p) => words(p).some((w) => title.includes(w)))) { rolePts = 1; roleNote = 'role partly matches'; }

  const locs = String(form.Location || '').toLowerCase().split(/[\/,|]/).map((s) => s.trim()).filter(Boolean);
  const locWords = new Set(locs.flatMap((l) => words(l)));

  // 2) Skill overlap with the offer / CV summary (location words don't count as skills)
  const offerTerms = [...new Set(words(form['What you offer / your CV summary']))].filter((t) => !locWords.has(t));
  const hits = offerTerms.filter((t) => text.includes(t));
  const skillPts = hits.length >= 3 ? 2 : hits.length >= 1 ? 1 : 0;

  // 3) Location match
  const locText = `${text} ${String(lead.Location || '').toLowerCase()}`;
  const locPts = locs.some((l) => locText.includes(l)) ? 1 : 0;

  const score = Math.min(5, 1 + rolePts + skillPts + locPts);
  out['Fit Score'] = score;
  out['Fit Reason'] = `Keyword score: ${roleNote}; ${hits.length} skill match(es)` +
    (hits.length ? ` (${hits.slice(0, 5).join(', ')})` : '') + (locPts ? '; location matches' : '');

  if (isDuplicate) out.outcome = 'duplicate';
  else if (score < cfg.minScore) out.outcome = 'low_fit';
  else out.outcome = 'qualified';
}

out['Angle / Tip'] = out['Angle / Tip'] || '';
out.qualified = out.outcome === 'qualified';
out.needContact = out.qualified && cfg.findContacts && Boolean(out['Company']);

return [{ json: out }];

// Build AI Prompt
// Builds the Gemini request that qualifies one job posting.
// Clients mode: "would this company buy what I offer?"  Jobs mode: "does this job fit my CV?"

const lead = $input.first().json;
const cfg = lead.config;
const form = lead.form;
const isClients = lead.mode === 'clients';

// Rate-limit Gemini calls
const gap = Date.now() - Number(lead.lastAiCallAt || 0);
const minGap = Number(cfg.aiMinIntervalMs || 4500);
if (gap < minGap) await new Promise((r) => setTimeout(r, minGap - gap));

const offer = String(form['What you offer / your CV summary'] || '').slice(0, 2000);

const task = isClients
  ? `You qualify B2B sales leads. A company that posts a job opening is a potential client for the user.
The user offers: """${offer}"""
Score how likely this company would buy the user's services, based on what it is hiring for.
5 = the hiring need matches the offer exactly; 3 = related; 1 = unrelated.`
  : `You screen job postings for a job seeker.
Candidate profile: """${offer}"""
Score how well this job fits the candidate (skills, seniority, location).
5 = excellent fit; 3 = partial fit; 1 = poor fit.`;

const prompt = `${task}

Search result to evaluate:
Board: ${lead['Job Board']}
URL: ${lead['Job URL']}
Title: ${lead.rawTitle || ''}
Snippet: ${lead.Snippet}
Target role keywords: ${form['Role or skill keywords'] || ''}
Target location: ${form.Location || ''}

Rules:
- Use only the information above. Do not invent facts; use "" when unknown.
- is_job_posting = false if this is a list or search page, an article, or a company page rather than one specific job.
- company, role, location: as stated in the posting.
- fit_reason: one short sentence.
- angle: ${isClients ? 'one sentence on how to pitch this company' : 'one sentence on how to tailor the application'}.`;

const geminiBody = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0.2,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        is_job_posting: { type: 'BOOLEAN' },
        company: { type: 'STRING' },
        role: { type: 'STRING' },
        location: { type: 'STRING' },
        fit_score: { type: 'INTEGER' },
        fit_reason: { type: 'STRING' },
        angle: { type: 'STRING' },
      },
      required: ['is_job_posting', 'company', 'role', 'location', 'fit_score', 'fit_reason', 'angle'],
    },
  },
};

return [{ json: { ...lead, geminiBody, lastAiCallAt: Date.now() } }];

// Parse AI Result
// Reads Gemini's JSON verdict, merges it into the lead, and decides what happens next.
// Outcomes: qualified | low_fit | not_job | duplicate. If Gemini fails, the lead is kept unscored.

const lead = $('Build AI Prompt').item.json;
const cfg = lead.config;
const resp = $input.first().json || {};

function dedupeSlug(s) {
  return String(s || '').toLowerCase()
    .replace(/\b(pvt|private|ltd|limited|inc|llc|co|company|corp)\b\.?/g, '')
    .replace(/[^a-z0-9]+/g, '');
}

let ai = null;
let aiError = '';
try {
  if (resp.error) throw new Error(resp.error.message || JSON.stringify(resp.error));
  const text = (resp.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('').trim();
  if (!text) throw new Error('Empty Gemini response');
  ai = JSON.parse(text.replace(/^```(?:json)?\s*|\s*```$/g, ''));
} catch (e) {
  aiError = String(e.message || e).slice(0, 200);
}

const out = { ...lead };
delete out.geminiBody;
out.aiError = aiError;

if (ai) {
  out['Company'] = String(ai.company || '').trim() || lead['Company'];
  out['Job Title'] = String(ai.role || '').trim() || lead['Job Title'];
  out['Location'] = String(ai.location || '').trim() || lead['Location'];
  const score = Math.min(5, Math.max(1, Math.round(Number(ai.fit_score) || 1)));
  out['Fit Score'] = score;
  out['Fit Reason'] = String(ai.fit_reason || '').trim();
  out['Angle / Tip'] = String(ai.angle || '').trim();
} else {
  out['Fit Reason'] = `Not scored (AI error: ${aiError})`;
}

// Re-compute the dedupe key with the cleaner AI fields
out['Dedupe Key'] = out['Company'] && out['Job Title']
  ? `${lead.mode}|${dedupeSlug(out['Company'])}|${dedupeSlug(out['Job Title'])}` : '';

const knownKeys = new Set(lead.seenKeys || []);
for (const row of $('Load Existing Leads').all()) {
  const k = row.json && row.json['Dedupe Key'];
  if (k) knownKeys.add(String(k));
}

if (ai && ai.is_job_posting === false) out.outcome = 'not_job';
else if (out['Dedupe Key'] && knownKeys.has(out['Dedupe Key'])) out.outcome = 'duplicate';
else if (ai && out['Fit Score'] < cfg.minScore) out.outcome = 'low_fit';
else out.outcome = 'qualified';

out.qualified = out.outcome === 'qualified';
out.needContact = out.qualified && cfg.findContacts && Boolean(out['Company']);

return [{ json: out }];

// Build Contact Query
// Clients mode only: search LinkedIn profiles for a decision-maker at the hiring company.

const lead = $input.first().json;
const cfg = lead.config;

const company = String(lead['Company'] || '').replace(/"/g, '').trim();
const city = String(lead.form.Location || '').split(/[\/,|]/)[0].trim();
const cityPart = city && !/remote|anywhere|worldwide/i.test(city) ? city : '';
const roles = (cfg.contactRoles || []).join(' OR ');

const query = `site:linkedin.com/in/ "${company}" (${roles}) ${cityPart}`.replace(/\s+/g, ' ').trim();

return [{ json: { ...lead, contactBody: { query, limit: 5 } } }];

// Extract Contact
// Picks the first LinkedIn profile that clearly mentions the company. Leaves blanks if unsure.

const lead = $('Build Contact Query').item.json;
const resp = $input.first().json || {};
const out = { ...lead };
delete out.contactBody;

const results = Array.isArray(resp?.data?.web) ? resp.data.web
  : Array.isArray(resp?.data) ? resp.data : [];

const generic = new Set(['pvt', 'private', 'ltd', 'limited', 'inc', 'llc', 'the', 'and', 'company',
  'group', 'solutions', 'technologies', 'technology', 'tech', 'software', 'services', 'international']);
const tokens = String(lead['Company'] || '').toLowerCase().split(/[^a-z0-9]+/)
  .filter((t) => t.length >= 3 && !generic.has(t));

function parsePerson(title) {
  const cleaned = String(title || '').replace(/\s+/g, ' ').trim()
    .replace(/\s*[-–—|]\s*LinkedIn\s*$/i, '');
  const parts = cleaned.split(/\s+[-–—|]\s+/).map((s) => s.trim()).filter(Boolean);
  return { name: parts[0] || '', title: parts[1] || '' };
}

if (tokens.length) {
  for (const r of results) {
    const url = String(r.url || '');
    const m = url.match(/linkedin\.com\/in\/([^/?#]+)/i);
    if (!m) continue;
    const hay = `${r.title || ''} ${r.description || ''}`.toLowerCase();
    if (!tokens.some((t) => hay.includes(t))) continue;
    const p = parsePerson(r.title);
    out['Contact Name'] = p.name;
    out['Contact Title'] = p.title;
    out['Contact LinkedIn'] = `https://www.linkedin.com/in/${decodeURIComponent(m[1]).toLowerCase()}`;
    break;
  }
}

return [{ json: out }];

// Prepare Row
// Single entry point before writing to the sheet (with or without contact lookup).

const lead = $input.first().json;
return [{
  json: {
    ...lead,
    'Contact Name': lead['Contact Name'] || '',
    'Contact Title': lead['Contact Title'] || '',
    'Contact LinkedIn': lead['Contact LinkedIn'] || '',
  },
}];

// Tag Created
const lead = $('Prepare Row').item.json;
return [{ json: { ...lead, outcome: 'created' } }];

// Tag Missed (no usable search result) / Tag Skipped (rejected by AI) share this logic
const lead = $input.first().json;
return [{
  json: {
    ...lead,
    outcome: lead.outcome && !['candidate', 'qualified'].includes(lead.outcome) ? lead.outcome : 'invalid',
  },
}];

// Tag Missed (no usable search result) / Tag Skipped (rejected by AI) share this logic
const lead = $input.first().json;
return [{
  json: {
    ...lead,
    outcome: lead.outcome && !['candidate', 'qualified'].includes(lead.outcome) ? lead.outcome : 'invalid',
  },
}];

// Update Counters
// Records the outcome of this pass and decides whether the loop continues.

const c = $input.first().json;
const cfg = c.config;
const outcome = c.outcome || 'invalid';

let newLeadsSaved = Number(c.newLeadsSaved || 0);
let lowFitCount = Number(c.lowFitCount || 0);
let duplicateCount = Number(c.duplicateCount || 0);
let notJobCount = Number(c.notJobCount || 0);
let aiErrorCount = Number(c.aiErrorCount || 0);
let consecutiveUnsuccessfulAttempts = Number(c.consecutiveUnsuccessfulAttempts || 0);
let consecutiveApiErrors = Number(c.consecutiveApiErrors || 0);
let lastApiError = c.lastApiError || '';
const attemptIndex = Number(c.attemptIndex || 0) + 1;

const seenUrls = Array.isArray(c.seenUrls) ? [...c.seenUrls] : [];
const seenKeys = Array.isArray(c.seenKeys) ? [...c.seenKeys] : [];
if (c.normalizedUrl && !seenUrls.includes(c.normalizedUrl)) seenUrls.push(c.normalizedUrl);
const key = c['Dedupe Key'];
if (key && ['created', 'low_fit', 'not_job', 'duplicate'].includes(outcome) && !seenKeys.includes(key)) {
  seenKeys.push(key);
}

if (outcome === 'created') { newLeadsSaved += 1; consecutiveUnsuccessfulAttempts = 0; }
else consecutiveUnsuccessfulAttempts += 1;

if (outcome === 'low_fit') lowFitCount += 1;
if (outcome === 'duplicate') duplicateCount += 1;
if (outcome === 'not_job') notJobCount += 1;
if (c.aiError) aiErrorCount += 1;

if (outcome === 'api_error') { consecutiveApiErrors += 1; lastApiError = c.apiError || lastApiError; }
else consecutiveApiErrors = 0;

const maxApi = Number(cfg.maxConsecutiveApiErrors || 3);
const shouldContinue =
  newLeadsSaved < c.targetLeads &&
  consecutiveUnsuccessfulAttempts < c.maxRetries &&
  consecutiveApiErrors < maxApi &&
  attemptIndex < c.maxAttempts;

let status = 'running';
if (newLeadsSaved >= c.targetLeads) status = 'target_reached';
else if (consecutiveApiErrors >= maxApi) status = 'api_error';
else if (consecutiveUnsuccessfulAttempts >= c.maxRetries) status = 'retry_limit_reached';
else if (attemptIndex >= c.maxAttempts) status = 'max_attempts_reached';

return [{
  json: {
    form: c.form,
    mode: c.mode,
    modeLabel: c.modeLabel,
    config: cfg,
    targetLeads: c.targetLeads,
    newLeadsSaved,
    lowFitCount,
    duplicateCount,
    notJobCount,
    aiErrorCount,
    consecutiveUnsuccessfulAttempts,
    consecutiveApiErrors,
    lastApiError,
    lastAiCallAt: c.lastAiCallAt || 0,
    maxRetries: c.maxRetries,
    maxAttempts: c.maxAttempts,
    attemptIndex,
    seenUrls,
    seenKeys,
    candidateQueue: Array.isArray(c.candidateQueue) ? c.candidateQueue : [],
    existingLeadCount: c.existingLeadCount,
    searchRunId: c.searchRunId,
    startedAt: c.startedAt,
    shouldContinue,
    lastOutcome: outcome,
    status,
    useQueue: false,
  },
}];

// Run Summary
// Final stats for the execution log and the "Run Log" sheet tab.

const s = $input.first().json;
const skipped = Number(s.lowFitCount || 0) + Number(s.duplicateCount || 0) + Number(s.notJobCount || 0);

return [{
  json: {
    'Run ID': s.searchRunId,
    'Date': $now.toISODate(),
    'Time': $now.toFormat('HH:mm:ss'),
    'Mode': s.modeLabel,
    'Run By': s.form['Your name'] || '',
    'Keywords': s.form['Role or skill keywords'] || '',
    'Location': s.form.Location || '',
    'Ranking': s.config.rankingLabel || '',
    'Boards': (s.config.boards || []).map((b) => b.name).join(', '),
    'Target': s.targetLeads,
    'Saved': s.newLeadsSaved,
    'Skipped': skipped,
    'Low Fit': s.lowFitCount,
    'Duplicates': s.duplicateCount,
    'Attempts': s.attemptIndex,
    'AI Errors': s.aiErrorCount,
    'Status': s.status,
    'Last Error': s.lastApiError || '',
  },
}];
